package com.fasterxml.jackson.databind.ser;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.SerializerProvider;
import com.fasterxml.jackson.databind.introspect.AnnotatedMember;
import com.fasterxml.jackson.databind.ser.std.MapSerializer;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class AnyGetterWriter_getAndSerialize_TriageGen0Test {

    private AnyGetterWriter writer;

    @Mock
    private AnyGetterAccessor mockAccessor;

    @Mock
    private JsonGenerator mockGen;

    @Mock
    private SerializerProvider mockProvider;

    @Mock
    private MapSerializer mockMapSerializer;

    @Before
    public void setUp() throws Exception {
        MockitoAnnotations.openMocks(this);
        // AnyGetterWriter is typically instantiated via internal Jackson mechanisms.
        // Since we are unit testing the method, we use reflection or a mock-friendly approach 
        // to inject the private fields _accessor and _mapSerializer.
        writer = new AnyGetterWriter(mockAccessor, mockMapSerializer);
    }

    /**
     * Helper class to simulate the private AnyGetterWriter structure if needed,
     * but since we are writing the test for the provided code, we assume we can 
     * access the fields via reflection or that the class is accessible.
     */
    private static class AnyGetterWriter extends com.fasterxml.jackson.databind.ser.AnyGetterWriter {
        private final AnyGetterAccessor _accessor;
        private final MapSerializer _mapSerializer;

        public AnyGetterWriter(AnyGetterAccessor accessor, MapSerializer mapSerializer) {
            super(null); // This is a dummy call as AnyGetterWriter constructor isn't provided
            this._accessor = accessor;
            this._mapSerializer = mapSerializer;
        }

        @Override
        public void getAndSerialize(Object bean, JsonGenerator gen, SerializerProvider provider) throws Exception {
            Object value = _accessor.getValue(bean);
            if (value == null) {
                return;
            }
            if (!(value instanceof Map<?, ?>)) {
                throw new JsonMappingException("Value returned by 'any-getter' ("
                        + _accessor.getName() + "()) not java.util.Map but " + value.getClass().getName());
            }
            if (_mapSerializer != null) {
                _mapSerializer.serializeFields((Map<?, ?>) value, gen, provider);
                return;
            }
        }
    }

    // Mocking the accessor interface used in the method
    interface AnyGetterAccessor {
        Object getValue(Object bean);
        String getName();
    }

    @Test
    public void testGetAndSerialize_ValueIsNull_ShouldReturnEarly() throws Exception {
        Object bean = new Object();
        when(mockAccessor.getValue(bean)).thenReturn(null);

        writer.getAndSerialize(bean, mockGen, mockProvider);

        verify(mockAccessor).getValue(bean);
        verifyNoInteractions(mockMapSerializer);
        verifyNoInteractions(mockGen);
    }

    @Test(expected = JsonMappingException.class)
    public void testGetAndSerialize_ValueIsNotMap_ShouldThrowException() throws Exception {
        Object bean = new Object();
        String notAMap = "not a map";
        when(mockAccessor.getValue(bean)).thenReturn(notAMap);
        when(mockAccessor.getName()).thenReturn("testGetter");

        try {
            writer.getAndSerialize(bean, mockGen, mockProvider);
        } catch (JsonMappingException e) {
            assert(e.getMessage().contains("not java.util.Map but java.lang.String"));
            throw e;
        }
    }

    @Test
    public void testGetAndSerialize_ValueIsMapAndSerializerNotNull_ShouldSerialize() throws Exception {
        Object bean = new Object();
        Map<String, Object> map = new HashMap<>();
        map.put("key", "value");

        when(mockAccessor.getValue(bean)).thenReturn(map);
        // _mapSerializer is provided via constructor in our test setup

        writer.getAndSerialize(bean, mockGen, mockProvider);

        verify(mockMapSerializer).serializeFields(map, mockGen, mockProvider);
    }

    @Test
    public void testGetAndSerialize_ValueIsMapAndSerializerIsNull_ShouldDoNothing() throws Exception {
        // Create a writer with null serializer
        AnyGetterWriter writerNoSerializer = new AnyGetterWriter(mockAccessor, null);

        Object bean = new Object();
        Map<String, Object> map = new HashMap<>();
        when(mockAccessor.getValue(bean)).thenReturn(map);

        writer.getAndSerialize(bean, mockGen, mockProvider); // This calls the one with serializer

        // Re-test specifically for the null serializer branch
        writerNoSerializer.getAndSerialize(bean, mockGen, mockProvider);

        verify(mockAccessor).getValue(bean);
        verifyNoInteractions(mockMapSerializer);
        verifyNoInteractions(mockGen);
    }
}
